def F(n):
	(a, b) = (1, 0)
	for i in range(n):
		(a, b) = (b, a + b)
	return b

def ans(n, k):
	if n == 0:
		return []
	elif n == 1:
		return [1]
	elif k > F(n):
		return [2, 1] + [i + 2 for i in ans(n - 2, k - F(n))]
	else:
		return [1] + [i + 1 for i in ans(n - 1, k)]
(n, k) = map(int, input().split())
print(' '.join([str(i) for i in ans(n, k)]))
